mapper.select:
-- Select matching case by business unique key to avoid duplicate creation. SELECT mc.id AS matching_case_id, mc.public_code AS matching_case_code, mc.announcement_id, a.public_code AS announcement_code, mc.member_user_id, u.public_code AS member_user_code, mc.verification_id, pv.public_code AS verification_code, mc.status_code, mc.blocked_reason_code, mc.matched_at, mc.reviewed_by, mc.reviewed_at, mc.created_at, mc.updated_at, a.title AS announcement_title, a.agency_name, a.target_type_code, a.min_amount, a.max_amount, a.application_start_date, a.application_end_date, u.login_id AS member_login_id, u.name AS member_name, EXISTS ( SELECT 1 FROM application_progresses ap WHERE ap.matching_case_id = mc.id ) AS progress_created FROM matching_cases mc INNER JOIN announcements a ON a.id = mc.announcement_id INNER JOIN users u ON u.id = mc.member_user_id LEFT JOIN partner_verifications pv ON pv.id = mc.verification_id WHERE mc.announcement_id = #{announcementId} AND mc.member_user_id = #{memberUserId}
AND mc.verification_id = #{verificationId}
AND mc.verification_id IS NULL
